"""Reserva de estoque."""


class InvalidRequestError(ValueError):
    pass


class InsufficientStockError(Exception):
    pass


class KeyConflictError(Exception):
    pass


def _is_int(value):
    """Return whether value is an integer, but not a boolean."""
    return isinstance(value, int) and not isinstance(value, bool)


class InventoryService:
    def __init__(self, stock):
        if not isinstance(stock, dict):
            raise InvalidRequestError("stock must be a dict")
        if any(not isinstance(sku, str) or not _is_int(quantity) or quantity < 0
               for sku, quantity in stock.items()):
            raise InvalidRequestError("stock must map string skus to non-negative integers")

        self._stock = dict(stock)
        self._reservations = {}
        self._events = []

    @property
    def events(self):
        return [
            {
                "type": event["type"],
                "reservation_key": event["reservation_key"],
                "items": dict(event["items"]),
            }
            for event in self._events
        ]

    def available(self, sku):
        if not isinstance(sku, str) or sku not in self._stock:
            raise InvalidRequestError("unknown sku")
        return self._stock[sku]

    def reserve(self, reservation_key, items):
        # Validate the complete request before looking up an existing key.
        if not isinstance(reservation_key, str) or not reservation_key.strip():
            raise InvalidRequestError("reservation_key must be a non-empty string")
        if not isinstance(items, dict) or not items:
            raise InvalidRequestError("items must be a non-empty dict")

        key = reservation_key.strip()
        requested = {}
        for sku, quantity in items.items():
            if not isinstance(sku, str) or sku not in self._stock:
                raise InvalidRequestError("unknown sku")
            if not _is_int(quantity) or quantity <= 0:
                raise InvalidRequestError("quantity must be a positive integer")
            requested[sku] = quantity

        if key in self._reservations:
            if self._reservations[key] != requested:
                raise KeyConflictError(key)
            return {"reservation_key": key, "items": dict(requested), "replayed": True}

        # Check all items before changing any item: reservation is atomic.
        for sku, quantity in requested.items():
            if self._stock[sku] < quantity:
                raise InsufficientStockError(sku)
        for sku, quantity in requested.items():
            self._stock[sku] -= quantity

        self._reservations[key] = dict(requested)
        self._events.append({
            "type": "reservation_created",
            "reservation_key": key,
            "items": dict(requested),
        })
        return {"reservation_key": key, "items": dict(requested), "replayed": False}
import unittest

from inventory import (
    InsufficientStockError,
    InvalidRequestError,
    InventoryService,
    KeyConflictError,
)


class RequirementsInventoryTests(unittest.TestCase):
    def test_constructor_validates_and_copies_stock(self):
        stock = {"A": 3}
        service = InventoryService(stock)
        stock["A"] = 0
        self.assertEqual(service.available("A"), 3)

        for invalid in (None, {"A": True}, {"A": -1}, {1: 2}):
            with self.subTest(invalid=invalid):
                with self.assertRaises(InvalidRequestError):
                    InventoryService(invalid)

    def test_validation_precedes_replay_lookup(self):
        service = InventoryService({"A": 3})
        service.reserve(" key ", {"A": 1})
        with self.assertRaises(InvalidRequestError):
            service.reserve("key", {"A": 0})

    def test_normalized_key_and_conflict(self):
        service = InventoryService({"A": 3})
        first = service.reserve(" key ", {"A": 1})
        replay = service.reserve("key", {"A": 1})
        self.assertEqual(first["reservation_key"], "key")
        self.assertTrue(replay["replayed"])
        with self.assertRaises(KeyConflictError):
            service.reserve(" key ", {"A": 2})
        self.assertEqual(service.available("A"), 2)
        self.assertEqual(len(service.events), 1)

    def test_insufficient_multi_item_reservation_is_atomic(self):
        service = InventoryService({"A": 5, "B": 1})
        with self.assertRaises(InsufficientStockError):
            service.reserve("k", {"A": 2, "B": 2})
        self.assertEqual(service.available("A"), 5)
        self.assertEqual(service.available("B"), 1)
        self.assertEqual(service.events, [])

    def test_events_are_deep_copies(self):
        service = InventoryService({"A": 3})
        service.reserve("k", {"A": 1})
        events = service.events
        events.clear()
        events = service.events
        events[0]["items"]["A"] = 99
        events[0]["reservation_key"] = "changed"
        self.assertEqual(
            service.events,
            [{"type": "reservation_created", "reservation_key": "k", "items": {"A": 1}}],
        )

    def test_available_rejects_unknown_or_non_string_sku(self):
        service = InventoryService({"A": 1})
        for sku in ("Z", 1, None):
            with self.subTest(sku=sku):
                with self.assertRaises(InvalidRequestError):
                    service.available(sku)


if __name__ == "__main__":
    unittest.main()
